def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """

    if not name.endswith('Point'):
        name += 'Point'

    if not all(isinstance(field, tuple) and len(field) == 2 for field in fields):
        raise ValueError("Fields must be tuples of (name, type)")

    if not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a dictionary")

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        for name, value in zip(fields, args):
            setattr(self, name, value)

    cls_dict = {
        '__init__': __init__,
        '__fields__': fields,
        '__srid_map__': srid_map,
    }

    return type(name, (Point,), cls_dict)

