import time

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        cache_times = {}
        hargs_cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            hargs = hash((args, kwargs))
            if hargs in cache_times and time.time() - cache_times[hargs] <= maxsize:
                return cache[hargs]
            result = func(*args, **kwargs)
            hargs_cache[hargs] = args, kwargs
            if len(cache) >= maxsize:
                lru_key = min(cache_times, key=cache_times.get)
                del cache[lru_key]
                del cache_times[lru_key]
                del hargs_cache[lru_key]
            cache[hargs] = result
            cache_times[hargs] = time.time()
            return result

        return wrapper

    return decorator
