def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Helper function to check if a class is a subclass of all other classes in the list
    def isSubclassOfAll(classToCheck, classList):
        return all(classToCheck is not cls and issubclass(classToCheck, cls) for cls in classList)

    # Sort classes to ensure order does not affect the result
    classes.sort(key=lambda x: x.__name__)

    # Reduce the list to its minimal equivalent
    minimal_classes = []
    for cls in classes:
        if isSubclassOfAll(cls, minimal_classes):
            minimal_classes.append(cls)

    return minimal_classes

