def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for arg in sequence:
        if isinstance(arg, Declaration):
            output.extend(arg.get_implements())
        elif isinstance(arg, tuple):
            output.extend(_normalizeargs(arg, output))
        else:
            output.append(arg)

    return output
