def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries")

    if level == 0:
        return {}

    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level if level == -1 else level - 1)
            if sub_diff:
                result[key] = sub_diff
        elif d1[key] != d2[key]:
            result[key] = d1[key]

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.min_coord or coord > self.max_coord:
        return

    index = int((coord - self.min_coord) / self.bin_width)
    if index >= len(self.bins):
        return

    self.bins[index] += weight

