def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use out-style parameters instead of the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style, then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    if not isinstance(many_params, Iterable):
        raise TypeError("many_params must be an iterable of parameter sets")

    converted_params = []
    formatted_sql = str(sql)

    for params in many_params:
        if isinstance(params, Mapping) and self.SQLParams.in_style == 'named':
            formatted_sql, named_params = format_single_named(sql, params)
            converted_params.append(named_params)
        elif isinstance(params, Sequence) and self.SQLParams.in_style == 'ordinal':
            formatted_sql, ordinal_params = format_single_ordinal(sql, params)
            converted_params.append(ordinal_params)
        else:
            raise ValueError("Invalid parameters for the specified SQL parameter style")

    return formatted_sql, converted_params

def format_single_named(sql: str, params: Mapping[Union[str, int], Any]) -> Tuple[str, Dict[Union[str, int], Any]]:
    named_params = {}
    for key, value in params.items():
        if isinstance(key, str):
            placeholder = ':' + key
        elif isinstance(key, int):
            placeholder = ':' + str(key)
        else:
            raise ValueError("Parameter keys must be either a string or an integer")
        if placeholder in sql:
            formatted_sql = sql.replace(placeholder, value)
            named_params[key] = value
        else:
            raise ValueError(f"SQL query does not contain the expected placeholder for parameter {key}")
    return formatted_sql, named_params

def format_single_ordinal(sql: str, params: Sequence[Any]) -> Tuple[str, List[Any]]:
    ordinal_params = []
    for i, value in enumerate(params):
        placeholder = ':' + str(i + 1)
        if placeholder in sql:
            formatted_sql = sql.replace(placeholder, value)
            ordinal_params.append(value)
        else:
            raise ValueError(f"SQL query does not contain the expected placeholder for parameter {i + 1}")
    return formatted_sql, ordinal_params
