def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Extract digests from manifest files
    digests_in_manifest = set()
    for manifest_file in manifest_files:
        try:
            with open(manifest_file, 'r') as file:
                for line in file:
                    parts = line.strip().split()
                    if len(parts) == 2:
                        digest_type, digest_value = parts
                        digests_in_manifest.add(digest_value)
        except FileNotFoundError:
            print(f"Manifest file {manifest_file} not found.")
        except Exception as e:
            print(f"Error reading manifest file {manifest_file}: {e}")

    # Check if all digests in digests_used are present in digests_in_manifest
    missing_digests = digests_used - digests_in_manifest
    if missing_digests:
        print(f"Missing digests: {missing_digests}")
        return False

    # Check if all digests in digests_in_manifest are used
    unused_digests = digests_in_manifest - digests_used
    if unused_digests:
        print(f"Unused digests: {unused_digests}")
        return False

    return True

