def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if all required keys are present
    required_keys = ['digest_algorithm', 'digest_value', 'files']
    for key in required_keys:
        if key not in fixity:
            raise KeyError(f"{key} is missing from fixity block")

    # Check if digest_algorithm is a string
    if not isinstance(fixity['digest_algorithm'], str):
        raise ValueError("digest_algorithm must be a string")

    # Check if digest_value is a string
    if not isinstance(fixity['digest_value'], str):
        raise ValueError("digest_value must be a string")

    # Check if files is a list
    if not isinstance(fixity['files'], list):
        raise ValueError("files must be a list")

    # Check if all files in the fixity block are in the manifest
    for file in fixity['files']:
        if file not in manifest_files:
            raise ValueError(f"File {file} in fixity block is not listed in the manifest")
