def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def simplify_expression(expr):
        if isinstance(expr, (tuple, list)):
            simplified_expr = []
            for sub_expr in expr:
                simplified_expr.append(simplify_expression(sub_expr))
            return simplified_expr

        if isinstance(expr, (bool, int)):
            return expr

        if isinstance(expr, str) and expr.startswith("not "):
            return simplify_expression(expr[4:])

        op, left, right = expr

        if op == "and":
            if left == right:
                return left
            elif left == "true":
                return "true"
            elif right == "true":
                return left
            elif left == "false" or right == "false":
                return "false"
            elif isinstance(left, (tuple, list)) and "or" in left:
                inner_op, inner_left, inner_right = left
                if inner_op == "or" and inner_right == right:
                    return "true"
                elif inner_op == "or" and inner_left == right:
                    return inner_left

        elif op == "or":
            if left == right:
                return left
            elif left == "false":
                return right
            elif right == "false":
                return left
            elif left == "true" or right == "true":
                return "true"
            elif isinstance(left, (tuple, list)) and "and" in left:
                inner_op, inner_left, inner_right = left
                if inner_op == "and" and inner_right == right:
                    return "true"
                elif inner_op == "and" and inner_left == right:
                    return inner_left

        return expr

    new_args = []
    for arg in args:
        new_args.append(simplify_expression(arg))

    return new_args

