def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory_digests = {}
    content_digests = {}

    # Load digests from the root inventory file
    with open('root_inventory.txt', 'r') as file:
        for line in file:
            version, digest = line.strip().split(':')
            root_inventory_digests[int(version)] = digest

    # Validate each version directory and record any differences in content digests
    for version in version_dirs:
        version_number = int(version)
        inventory_file = f'{version}/inventory.txt'

        if version_number not in root_inventory_digests:
            raise ValueError(f'Inventory file missing for version {version_number}')

        with open(inventory_file, 'r') as file:
            for line in file:
                content, digest = line.strip().split(':')
                if content not in content_digests:
                    content_digests[content] = digest
                if content_digests[content] != digest:
                    print(f'Mismatch in digest for content {content} in version {version_number}')

    # Check any content digests that were only in the root inventory
    for content, digest in root_inventory_digests.items():
        if content not in content_digests:
            raise ValueError(f'Content with digest {digest} from root inventory not found in version directories')

