def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_  # Default to bin content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid value for get_coordinate. Must be 'left', 'right', or 'middle'.")

    if not all(isinstance(name, str) for name in field_names):
        raise ValueError("field_names must be a tuple of strings.")

    if len(field_names) != len({name for name in field_names}):
        raise ValueError("field_names must contain unique values.")

    if scale is None:
        scale = hist.scale

    points = []
    for bin_ in hist:
        value = make_value(bin_)
        if isinstance(value, tuple):
            x, y = value
        else:
            x, y = get_bin_coordinates(bin_, get_coordinate)
            y = value

        points.append((x, y, scale))

    graph = Graph(points, field_names=field_names)
    return graph

def get_bin_coordinates(bin_, get_coordinate):
    if get_coordinate == "left":
        x = bin_.edges[0]
    elif get_coordinate == "right":
        x = bin_.edges[1]
    elif get_coordinate == "middle":
        x = (bin_.edges[0] + bin_.edges[1]) / 2
    return x, bin_.content
