from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        return json.loads(document)
    except json.JSONDecodeError:
        pass  # Fallback to XRD parsing

    from lxml import etree
    try:
        root = etree.fromstring(document)
        data = {}
        for element in root:
            if element.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}subject':
                data['subject'] = element.text
            elif element.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}link':
                attrs = element.attrib
                data.setdefault('links', []).append(attrs)
        return data
    except etree.XMLSyntaxError:
        raise ValueError("Invalid document format for Diaspora webfinger")
