def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    import yaml

    if not yaml_file or not isinstance(yaml_file, str):
        raise ValueError("Invalid yaml_file path")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
            if not data:
                raise IRValidatorException("YAML file is empty")

            # Assuming required fields are defined in cls.REQUIRED_FIELDS
            for field in cls.REQUIRED_FIELDS:
                if field not in data:
                    raise IRValidatorException(f"Missing required field: {field}")

            return data
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file not found: {yaml_file}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    if 'include' not in parser_dict:
        return

    include_dict = parser_dict['include']

    if not isinstance(include_dict, dict):
        raise ValueError("Invalid include directive. It should be a dictionary.")

    for key, value in include_dict.items():
        if not isinstance(key, str):
            raise ValueError(f"Invalid key in include directive: {key}. It should be a string.")

        if not isinstance(value, str):
            raise ValueError(f"Invalid value in include directive: {value}. It should be a string.")

        if key == value:  # self reference is allowed
            continue

        try:
            with open(value, 'r') as file:
                content = file.read()
                include_dict[key] = content
        except IOError:
            raise FileNotFoundError(f"Failed to open file: {value}.")
        except Exception as e:
            raise Exception(f"Failed to read file: {value}. Error: {str(e)}")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    if hasattr(self, 'spec'):
        defaults.update(self.spec.get('defaults', {}))
    if hasattr(self, 'context'):
        defaults.update(self.context.get('defaults', {}))
    if hasattr(self, 'config'):
        defaults.update(self.config.get('defaults', {}))
    return defaults

