def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args: the dict of arguments from files
    """
    deprecated_args = []

    # Check for deprecated CLI arguments
    for key, value in cli_args.items():
        if key.startswith('--deprecated-'):
            deprecated_args.append(key)

    # Check for deprecated arguments in answer file
    for key, value in answer_file_args.items():
        if key.startswith('--deprecated-'):
            deprecated_args.append(key)

    # If there are deprecated arguments, print a warning
    if deprecated_args:
        print("Deprecated arguments detected:")
        for arg in deprecated_args:
            print(f"- {arg}")
        raise ValueError("Deprecated arguments are not allowed. Please update your command line arguments or configuration files.")
