def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if self._evaluate_condition(condition, command_name, args):
                matched_args.append(option['name'])
    return matched_args

def _evaluate_condition(self, condition, command_name, args):
    """Evaluate the condition for a required argument.

    :param condition: the condition to evaluate.
    :param command_name: the command name.
    :param args: the received input arguments
    :return: bool, whether the condition is satisfied
    """
    components = condition.split()
    if len(components) != 3:
        raise ValueError(f"Invalid condition format for '{command_name}': {condition}")
    arg_name, operator, value = components

    if arg_name not in args:
        return False

    arg_value = args[arg_name]
    if operator == 'eq':
        return arg_value == value
    elif operator == 'ne':
        return arg_value != value
    elif operator == 'le':
        return arg_value <= value
    elif operator == 'lt':
        return arg_value < value
    elif operator == 'ge':
        return arg_value >= value
    elif operator == 'gt':
        return arg_value > value
    else:
        raise ValueError(f"Invalid operator in condition for '{command_name}': {condition}")
```

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not args or not isinstance(args, dict):
        raise ValueError("Invalid arguments provided.")

    for key, value in args.items():
        if not isinstance(value, str):
            raise TypeError(f"Value for key '{key}' must be a string.")

        # Assuming a default maximum length of 255 characters if not specified
        max_length = 255

        if len(value) > max_length:
            raise ValueError(f"Value for key '{key}' exceeds the maximum length of {max_length} characters.")

