def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """

    choices = getattr(self, 'choices', {})
    for arg, value in args.items():
        if arg in choices and value not in choices[arg]:
            raise ValueError(f"Invalid value '{value}' for argument '{arg}'. Available choices are: {', '.join(choices[arg])}")
