def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    for arg in args:
        if 'min' in arg and 'max' in arg and 'value' in arg:
            if arg['value'] < arg['min'] or arg['value'] > arg['max']:
                raise ValueError(f"Value {arg['value']} is out of range. It should be between {arg['min']} and {arg['max']}")

